const {
  createScreen,
  findScreensByCinemaId,
  findScreenById,
  findSeatCategoriesByScreen,
  createScreenType,
  findScreenTypes,
  deleteScreenById,
} = require('../models/screenModel');
const { insertSeatsBatch } = require('../utils/seatService');

const validateRowRanges = (row_ranges) => {
  // Collect every (row, col) seat label generated by each range and detect duplicates
  const seen = new Set();
  for (const { rowStart, rowEnd, cols } of row_ranges) {
    const startCode = rowStart.toUpperCase().charCodeAt(0);
    const endCode = rowEnd.toUpperCase().charCodeAt(0);
    if (startCode > endCode) {
      return `rowStart "${rowStart}" must be <= rowEnd "${rowEnd}"`;
    }
    for (let r = startCode; r <= endCode; r++) {
      for (let c = 1; c <= cols; c++) {
        const key = `${String.fromCharCode(r)}${c}`;
        if (seen.has(key)) {
          return `Seat ${key} is covered by more than one range — ranges must not overlap`;
        }
        seen.add(key);
      }
    }
  }
  return null;
};

const createScreenController = async (req, res) => {
  const { name, cinema_id, screen_type_id, row_ranges } = req.body;
  if (!name || !cinema_id || !screen_type_id || !row_ranges) {
    return res.status(400).json({
      error: 'Screen name, cinema ID, screen type, and row ranges are required',
    });
  }

  const overlapError = validateRowRanges(row_ranges);
  if (overlapError) {
    return res.status(400).json({ error: overlapError });
  }

  const total_capacity = row_ranges.reduce((sum, r) => {
    const rows = r.rowEnd.charCodeAt(0) - r.rowStart.charCodeAt(0) + 1;
    return sum + rows * r.cols;
  }, 0);

  console.log('Calculated total capacity:', total_capacity);

  let newScreen;
  try {
    newScreen = await createScreen(
      cinema_id,
      name,
      screen_type_id,
      total_capacity
    );

    for (let i = 0; i < row_ranges.length; i++) {
      const { rowStart, rowEnd, cols, category_id } = row_ranges[i];
      if (!category_id) {
        return res
          .status(400)
          .json({ error: 'Category ID is required for each row range' });
      }
      if (!Number.isInteger(cols) || cols <= 0) {
        return res
          .status(400)
          .json({ error: 'Cols must be a positive integer' });
      }
      if (!/^[A-Z]$/i.test(rowStart) || !/^[A-Z]$/i.test(rowEnd)) {
        return res
          .status(400)
          .json({ error: 'Row labels must be single letters A-Z' });
      }
      let seats = [];
      for (let r = rowStart.charCodeAt(0); r <= rowEnd.charCodeAt(0); r++) {
        for (let c = 1; c <= cols; c++) {
          seats.push({
            row_label: String.fromCharCode(r),
            column_label: c,
            screen_id: newScreen.id,
            category_id,
          });
        }
      }
      await insertSeatsBatch(seats);
    }
    res.status(201).json(newScreen);
  } catch (error) {
    // Roll back the screen record if seat insertion failed
    if (newScreen) {
      await deleteScreenById(newScreen.id).catch(() => {});
    }
    if (error.code === '23505') {
      // PostgreSQL unique_violation
      return res.status(400).json({
        error:
          'Duplicate seat detected — two ranges produce the same seat label',
      });
    }
    console.error('Error creating screen:', error);
    res.status(500).json({ error: 'Failed to create screen' });
  }
};

const getScreensByCinemaId = async (req, res) => {
  try {
    const { cinema_id } = req.params;
    const screens = await findScreensByCinemaId(cinema_id);
    res.status(200).json({ data: screens });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

const getScreenById = async (req, res) => {
  try {
    const { id } = req.params;
    const screen = await findScreenById(id);
    res.status(200).json(screen);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

const getSeatCategoriesByScreen = async (req, res) => {
  try {
    const { screen_id } = req.params;
    const seat_categories = await findSeatCategoriesByScreen(screen_id);
    res.status(200).json(seat_categories);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

const createScreenTypeController = async (req, res) => {
  const { name, description } = req.body;
  if (!name) {
    return res.status(400).json({ error: 'Screen type name is required' });
  }
  try {
    const newScreenType = await createScreenType(name, description);
    res.status(201).json(newScreenType);
  } catch (error) {
    console.error('Error creating screen type:', error);
    res.status(500).json({ error: 'Failed to create screen type' });
  }
};

const getScreenTypesController = async (req, res) => {
  try {
    const screenTypes = await findScreenTypes();
    res.status(200).json(screenTypes);
  } catch (error) {
    console.error('Error fetching screen types:', error);
    res.status(500).json({ error: 'Failed to fetch screen types' });
  }
};

module.exports = {
  createScreenController,
  getScreensByCinemaId,
  getScreenById,
  getSeatCategoriesByScreen,
  createScreenTypeController,
  getScreenTypesController,
};
